    "text.0718": "板图与封面由当前网格和已选耗材重新渲染。Auxiliaries 中原作者的 Model/Profile Pictures 属于历史参考，未改写。拾取 ID 图保留原版。",
    "text.0719": "原始 4 槽保留，新颜色追加同材料模板；材质、硬度、流量、温度等参数按原槽复制。产品识别信息写入本清单。",
    "text.0720": "导出的是可编辑项目，不含切片 G-code。请在 Bambu Studio 中复核并重新切片。",
    "text.0721": "TPU 90A 沿用原硬度与参数，使用外置进料，不通过 P1P 的 AMS 进料。",
    "text.0722": "原 4 槽冲刷量沿用源表；新增颜色间用源表最大值作临时值。切片前须按新颜色重新计算冲刷量。",
    "text.0723": "官方色表用于屏幕预览，半透明外观为示意；未核验库存、价格或实物色差。",
    "text.0724": "板 1 含多种 TPU 颜色；这些软料不能通过 AMS 自动换色，需由商家拆分任务或另行安排换料。当前项目保留原摆放。",
    "text.0725": "部分 PLA 板包含多色，需要匹配实际 AMS / 换料方案并检查擦料塔。",
    "text.0726": "本版最多支持 ",
    "text.0727": " 个耗材槽（包含原始 4 槽），请减少颜色后导出。",
    "text.0728": " 尚未选择实际耗材；目标色不能直接作为产品导出。",
    "text.0729": " 必须保持 ",
    "text.0730": "，不能替换材料或硬度。",
