    "text.0718": "板圖與封面由當前網格和已選耗材重新渲染。Auxiliaries 中原作者的 Model/Profile Pictures 屬於歷史參考，未改寫。拾取 ID 圖保留原版。",
    "text.0719": "原始 4 槽保留，新顏色追加同材料模板；材質、硬度、流量、溫度等參數按原槽複製。產品識別信息寫入本清單。",
    "text.0720": "導出的是可編輯項目，不含切片 G-code。請在 Bambu Studio 中復核並重新切片。",
    "text.0721": "TPU 90A 沿用原硬度與參數，使用外置進料，不通過 P1P 的 AMS 進料。",
    "text.0722": "原 4 槽沖刷量沿用源表；新增顏色間用源表最大值作臨時值。切片前須按新顏色重新計算沖刷量。",
    "text.0723": "官方色表用於螢幕預覽，半透明外觀為示意；未核驗庫存、價格或實物色差。",
    "text.0724": "板 1 含多種 TPU 顏色；這些軟料不能通過 AMS 自動換色，需由商家拆分任務或另行安排換料。當前項目保留原擺放。",
    "text.0725": "部分 PLA 板包含多色，需要匹配實際 AMS / 換料方案並檢查擦料塔。",
    "text.0726": "本版最多支持 ",
    "text.0727": " 個耗材槽（包含原始 4 槽），請減少顏色後導出。",
    "text.0728": " 尚未選擇實際耗材；目標色不能直接作為產品導出。",
    "text.0729": " 必須保持 ",
    "text.0730": "，不能替換材料或硬度。",
