    "text.0718": "Plates and covers are re-rendered with the current mesh and selected filaments. Model/Profile Pictures from the original author in Auxiliaries are for historical reference and not overwritten. Picked ID images retain the original version.",
    "text.0719": "Original 4 slots are retained, new colors added following the same material template; material, hardness, flow, temperature, and other parameters are copied from the original slots. Product identification information is written into this list.",
    "text.0720": "The exported item is editable and does not include sliced G-code. Please review and re-slice in Bambu Studio.",
    "text.0721": "TPU 90A follows the original hardness and parameters, uses external feeding, not through P1P AMS feed.",
    "text.0722": "Original 4-slot purge amount follows the source table; temporary values for new colors use the maximum from the source table. Purge amounts need to be recalculated according to the new color before slicing.",
    "text.0723": "Official color chart is for screen preview; translucent appearance is indicative; stock, price, or physical color differences are not verified.",
    "text.0724": "Plate 1 contains multiple TPU colors; these soft materials cannot automatically change color through AMS, sellers need to split tasks or arrange material changes separately. Current project retains original placement.",
    "text.0725": "Some PLA plates contain multiple colors, need to match actual AMS/material change plan and check wipe tower.",
    "text.0726": "This version supports up to ",
    "text.0727": " filament slots (including the original 4 slots), please reduce the colors before exporting.",
