    "text.0184": "一致する色がありません。",
    "text.0185": "このブランドには元ファイルと同じTPU 90Aの柔らかい素材はありません。ソフトパッドは拓竹 TPU 90Aを使用するか、「自由調色」で先に色を決めてください。",
