    "text.0307": "{v2} パーツ → 最も近い：{v3} {v4}",
    "text.0308": "他に {v0} 個のパーツは自由色や示意ブランド色を使用。エクスポートする3MFには実際の消耗品スロットを記録する必要あり、現在は拓竹色表のみ対応。",
    "text.0309": "とりあえずエクスポートしない",
