    "error.export.22": "このバージョンは{v0}の消耗品スロット(元の4スロットを含む)まで対応しています。色を除去した後はエクスポートしてください。",
    "error.export.23": "エクスポートサムネイルが欠けています。モデルの読み込みを待ってから再試行してください。",
