    "error.export.25": "{v0}実際の消耗品はまだ選択されていません;ターゲットカラーは製品として直接エクスポートできません。",
    "error.export.26": "{v0}は{v1}のままで、材料や硬度を置き換えることはできない。",
    "error.export.27": "ソース部品のラベルが重複または不一致。",
    "error.export.28": "サムネイル形式は無効です。",
    "error.validation.29": "消耗品カラーチャートが読み込まれていません",
    "error.validation.30": "サーバーがモデル資産をロードしていないため、一時的にエクスポートできません",
    "error.validation.31": "サーバーがモデル資産をロードしていないため、一時的にエクスポートできません",
    "text.0718": "ボードとカバーは現在のメッシュと選択した消耗品で再レンダリングされます。Auxiliaries の原作者の Model/Profile Pictures は歴史的参照で、書き換えられていません。ID 画像はオリジナルを保持します。",
    "text.0719": "元の4スロットは保持され、新しい色は同じ材質テンプレに追加されます。材質、硬度、流量、温度などのパラメータは元のスロットにコピーされます。製品識別情報はこのリストに書き込みます。",
    "text.0720": "エクスポートされるのは編集可能なプロジェクトで、スライス済みG-codeは含まれていません。Bambu Studioで確認して再スライスしてください。",
    "text.0721": "TPU 90Aは元の硬度とパラメータを継続使用し、外部供給を利用し、P1PのAMS供給は通りません。",
    "text.0722": "元の4スロットの押出量は元の表を使用します。新しい色間は元の表の最大値を一時値として使用します。スライス前に新しい色で押出量を再計算する必要があります。",
    "text.0723": "公式カラーチャートは画面プレビュー用で、半透明の外観は示意です。在庫、価格、実物の色差は確認されていません。",
    "text.0724": "ボード1には複数のTPU色があります。これらの柔らかい材料はAMSによる自動カラー変更ができず、販売者がタスクを分けるか別途で材料交換を手配する必要があります。現在のプロジェクトは元の配置を保持します。",
    "text.0725": "一部のPLAボードは多色を含み、実際のAMS/材料交換のプランと照合し、スクラップタワーの確認が必要です。",
    "text.0726": "この版では最大対応 ",
    "text.0727": " 個の消耗スロット（元の4スロットを含む）です。色を減らしてからエクスポートしてください。",
    "text.0728": " 実際の消耗品をまだ選択していません。目標色はそのまま製品としてエクスポートできません。",
    "text.0729": " 必ず ",
    "text.0730": "を維持してください。材料や硬度を変更できません。",
