    "error.validation.9": "도식 번호가 잘못되었습니다",
    "error.schemes.not_owner": "이 계획은 네 것이 아니다",
    "error.validation.11": "{v0} 해답까지 저장하고, 먼저 일부는 삭제하세요",
    "error.validation.12": "그 작품은 존재하지 않는다",
    "error.validation.13": "출시 전에 모든 부품을 실제 소모품과 매칭해 주세요",
    "error.validation.14": "자신의 작품만 삭제할 수 있습니다",
    "error.validation.15": "그 작품은 존재하지 않는다",
    "error.validation.16": "자신의 작품을 평가할 수 없습니다",
    "error.validation.17": "등급은 1점에서 5점 사이여야 합니다",
    "error.validation.18": "색상 형식이 잘못되었습니다",
    "error.validation.19": "소모품 번호 체계가 잘못되었습니다",
    "error.export.20": "소스 모델이 일치하지 않습니다. 작업대를 새로고침하고 다시 시도해 주세요.",
    "error.export.21": "35개 부품 전원에 대한 소모품 분배가 제공되어야 합니다.",
    "error.export.22": "이 버전은 최대 {v0} 소모성 슬롯(원래 4개 슬롯 포함)을 지원합니다. 색상을 제거한 후 내보내기 바랍니다.",
    "error.export.23": "내보내기 썸네일이 누락되었습니다. 모델이 로드될 때까지 기다렸다가 다시 시도해 주세요.",
    "error.export.24": "현재 해결책의 썸네일 전체가 누락됨.",
    "error.export.25": "{v0} 실제 소모품은 아직 선택되지 않았습니다; 목표 색상은 제품으로 직접 내보낼 수 없습니다.",
    "error.export.26": "{v0}는 {v1}로 유지되어야 하며, 재료나 경도를 대체할 수 없습니다.",
    "error.export.27": "중복 또는 불일치 소스 부품 라벨링.",
    "error.export.28": "썸네일 형식이 유효하지 않습니다.",
    "error.validation.29": "소모품 색상표가 로드되지 않음",
    "error.validation.30": "서버가 모델 자산을 로드하지 않아 내보내기가 일시적으로 불가능합니다",
    "error.validation.31": "서버가 모델 자산을 로드하지 않아 일시적으로 내보내기가 불가능합니다",
    "text.0718": "보드 아트와 표지는 현재 그리드와 선택된 소모품에서 재렌더링되었습니다. 보조자료: 원작자의 모델/프로필 사진은 역사적 참고 자료이며 재작성되지 않았습니다. ID 이미지를 가져가고 원본을 유지하세요.",
    "text.0719": "원래 4개의 슬롯을 유지하고, 동일한 재료 템플릿에 새로운 색상이 추가되었습니다; 재료, 경도, 유량, 온도 등의 매개변수는 원래 슬롯에서 복사되었습니다. 제품 식별 정보는 이 목록에 기록되어 있습니다.",
    "text.0720": "내보내진 항목은 편집 가능하며 슬라이스된 G-코드는 포함되지 않습니다. Bambu Studio에서 검토 및 재슬라이스를 반드시 확인해 주세요.",
    "text.0721": "TPU 90A는 기존 경도와 파라미터를 그대로 사용하며, 외부 공급을 사용하고 P1P의 AMS 공급을 거치지 않습니다.",
    "text.0722": "기존 4 슬롯 플러싱량은 원본 테이블을 따릅니다; 색상 간의 새로운 값은 임시로 원본 테이블의 최대값을 사용합니다. 슬라이싱 전에 새로운 색상에 맞게 플러싱량을 재계산해야 합니다.",
    "text.0723": "공식 색상표는 화면 미리보기용이며, 반투명 외관은 참고용입니다; 재고, 가격 혹은 실제 색상차는 검증되지 않았습니다.",
    "text.0724": "보드 1에는 여러 TPU 색상이 포함되어 있습니다; 이 부드러운 재료들은 AMS 자동 색상 변경이 불가능하며, 판매자가 작업을 분리하거나 별도로 변경해야 합니다. 현재 프로젝트는 기존 배치를 유지합니다.",
    "text.0725": "일부 PLA 보드에는 여러 색상이 포함되어 있어, 실제 AMS/재료 변경 계획과 매칭하고 플러싱 타워를 점검해야 합니다.",
    "text.0726": "이번 버전은 최대 지원 ",
    "text.0727": " 개의 소모품 슬롯(원래 4 슬롯 포함), 색상을 줄인 후 내보내세요.",
    "text.0728": " 아직 실제 소모품이 선택되지 않았습니다; 목표 색상은 제품으로 바로 내보낼 수 없습니다.",
    "text.0729": " 반드시 유지해야 하는 ",
    "text.0730": ", 재료나 경도는 교체할 수 없습니다.",
