    "text.0799": "로그인 없이, 열면 같은 작품 만들 수 있어요.",
    "text.0800": "전체 색상 코드 복사, 오리 만들기에서 같은 작품 만들기",
    "text.0801": "공유 닫기",
    "text.0802": "좋아하는 색상 친구에게 보내기",
    "text.0803": "QR코드 스캔 또는 링크 열기, 바로 이 작품 보기",
