    "text.0808": "링크 열어 미리보기",
    "text.0809": "더 많은 포스터 설정",
    "text.0810": "포스터 생성 실패, 다시 열어 시도해주세요",
    "text.0811": "포스터 생성 완료, 브라우저에서 다운로드 확인",
    "text.0812": "이미지 복사됨, 친구에게 붙여넣기 가능",
    "text.0813": "이 브라우저는 이미지 복사를 지원하지 않으니 '포스터 저장' 사용",
    "text.0814": "작품 링크 복사됨",
    "text.0815": "아직 복사되지 않음",
    "text.0816": "'{v0}' 공유",
    "text.0817": "친구는 로그인 없이 작품을 볼 수 있습니다.",
    "text.0818": "이 계획은 아직 공개되지 않았으며, 포스터에는 작품 QR 코드 없음. 색상 코드를 먼저 복사하거나, 광장에 게시 후 작품 공유 가능",
    "text.0819": "사이트에서 공식 공유 주소가 아직 설정되지 않아 작품 링크 공유 불가",
    "text.0820": "작품 링크",
    "text.0821": "아직 복사되지 않음, 링크를 수동으로 선택해주세요",
    "text.0822": "색상 검색",
    "text.0823": "광장 내비게이션",
    "common.save": "저장",
    "common.saved": "「{name}」 저장됨"
