    "text.0393": "Jette un œil à comment tes amis ont peint XGO Duck. Si tu aimes, « Fais le pareil » pour l’emmener sur le plateau de peinture et continue les modifications, les adaptations seront sous l’arbre généalogique de l’œuvre originale.",
