    "error.export.26": "{v0} doit rester {v1}, le matériau ou la dureté ne peuvent pas être remplacés.",
    "error.export.27": "Identifiant de pièce source dupliqué ou incompatible.",
    "error.export.28": "Format de vignette invalide.",
    "error.validation.29": "Nuancier du matériau non chargé",
    "error.validation.30": "Le serveur n'a pas chargé les assets du modèle, impossible d'exporter pour le moment",
    "error.validation.31": "Le serveur n'a pas chargé les assets du modèle, impossible d'exporter pour le moment",
    "text.0718": "Le plan et la couverture sont rendus à nouveau à partir du maillage actuel et des matériaux sélectionnés. Les Model/Profile Pictures de l'auteur original dans Auxiliaries sont des références historiques, non réécrites. Les ID de capture restent dans la version originale.",
    "text.0719": "Les 4 emplacements originaux sont conservés, les nouvelles couleurs sont ajoutées selon le modèle du même matériau ; les paramètres de matériau, dureté, flux, température, etc. sont copiés à partir de l'emplacement original. Les informations d'identification du produit sont enregistrées dans cette liste.",
    "text.0720": "L'export est un projet éditable, sans G-code de découpe. Veuillez vérifier et re-découper dans Bambu Studio.",
    "text.0721": "TPU 90A conserve la dureté et les paramètres d'origine, utilise un approvisionnement externe, ne passe pas par l'AMS d'alimentation P1P.",
    "text.0722": "La quantité de lavage des 4 fentes d'origine est conservée selon le tableau source ; la nouvelle couleur utilise la valeur maximale du tableau source comme valeur temporaire. Avant de trancher, il faut recalculer la quantité de lavage selon la nouvelle couleur.",
    "text.0723": "La palette de couleurs officielle est utilisée pour la prévisualisation à l'écran, l'apparence semi-transparente est indicative ; les stocks, les prix ou les écarts de couleur réels n'ont pas été vérifiés.",
    "text.0724": "La planche 1 contient plusieurs couleurs de TPU ; ces matériaux souples ne peuvent pas changer de couleur automatiquement via AMS, le vendeur doit diviser la tâche ou organiser le changement de matériau séparément. Le placement original est conservé pour ce projet.",
    "text.0725": "Certaines planches PLA contiennent plusieurs couleurs, il faut faire correspondre avec le véritable plan AMS / changement de matériau et vérifier la tour de nettoyage des matériaux.",
    "text.0726": "Cette version supporte au maximum ",
    "text.0727": " emplacements de consommables (en incluant les 4 fentes d'origine), veuillez réduire les couleurs avant d'exporter.",
    "text.0728": " Aucun consommable réel n'a été sélectionné ; la couleur cible ne peut pas être directement exportée comme produit.",
    "text.0729": " Vous devez conserver ",
    "text.0730": ", ne pas remplacer le matériau ou la dureté.",
    "error.auth.required": "Veuillez vous connecter d'abord",
    "error.request.content_type": "Une requête JSON est nécessaire",
    "error.request.too_large": "La requête est trop volumineuse",
    "error.request.json": "La requête n'est pas un JSON valide",
    "error.request.format": "Format de requête incorrect",
    "error.server.failed": "Erreur serveur, veuillez consulter les logs",
    "error.request.not_found": "Interface inconnue",
    "error.request.static": "Les fichiers statiques sont fournis par le service frontend",
    "error.request.asset_missing": "L'actif n'existe pas",
