    "text.0718": "Board-Bild und Cover werden basierend auf aktuellem Mesh und ausgewähltem Material neu gerendert. Auxiliaries enthält historische Referenzen der Original-Model/Profile Pictures, keine Änderungen. Pick-ID-Bild bleibt Original",
    "text.0719": "Ursprüngliche 4 Slots bleiben erhalten, neue Farben werden zum gleichen Materialtemplate hinzugefügt; Material, Härte, Fluss, Temperatur usw. werden aus Original-Slot kopiert. Produktidentifikation wird in dieser Liste gespeichert",
    "text.0720": "Exportiert wird ein bearbeitbares Projekt, enthält keinen Slicing-G-Code. Bitte in Bambu Studio überprüfen und erneut slicen",
    "text.0721": "TPU 90A übernimmt die ursprüngliche Härte und Parameter, benutzt externes Zuführen, nicht das AMS-Zuführen über P1P.",
    "text.0722": "Ursprüngliche 4-Fach-Spülmenge wird aus der Ursprungstabelle übernommen; für neue Farben wird vorübergehend der maximale Wert aus der Ursprungstabelle verwendet. Vor dem Slicing muss die Spülmenge für neue Farben neu berechnet werden.",
    "text.0723": "Offizielle Farbtabellen dienen zur Bildschirmvorschau, halbtransparente Optik ist nur zur Veranschaulichung; Lagerbestand, Preise oder echte Farbabweichungen wurden nicht überprüft.",
    "text.0724": "Platte 1 enthält mehrere TPU-Farben; diese weichen Materialien können nicht über AMS automatisch farbgetauscht werden, Händler müssen Aufgaben aufteilen oder Farbersatz separat koordinieren. Das aktuelle Projekt behält die ursprüngliche Platzierung.",
    "text.0725": "Einige PLA-Platten enthalten mehrere Farben, diese müssen zum tatsächlichen AMS-/Farbersatzplan passen und den Interferenzturm prüfen.",
    "text.0726": "Diese Version unterstützt maximal ",
    "text.0727": " Verbrauchsmaterialschächte (einschließlich der ursprünglichen 4), bitte Farben reduzieren, bevor exportiert wird.",
    "text.0728": " Tatsächliche Verbrauchsmaterialien wurden noch nicht ausgewählt; Zielfarbe kann nicht direkt als Produkt exportiert werden.",
    "text.0729": " Muss beibehalten werden ",
    "text.0730": "Materialien oder Härte dürfen nicht ersetzt werden.",
