    "error.validation.30": "El servidor no cargó los activos del modelo, no se puede exportar temporalmente",
    "error.validation.31": "El servidor no cargó los activos del modelo, no se puede exportar temporalmente",
    "text.0718": "El tablero y la portada se renderizan de nuevo según la malla actual y los materiales seleccionados. Las Pictures del Modelo/Perfil del autor original en Auxiliaries son referencias históricas, no han sido modificadas. El ID de la imagen original se conserva.",
    "text.0719": "Las 4 ranuras originales se conservan, los nuevos colores se añaden siguiendo la plantilla del mismo material; parámetros como material, dureza, flujo, temperatura se copian de la ranura original. La información de identificación del producto se escribe en esta lista.",
    "text.0720": "Se exporta un proyecto editable, no incluye G-code de corte. Revisa y corta de nuevo en Bambu Studio.",
    "text.0721": "TPU 90A mantiene la dureza y parámetros originales, usando alimentación externa, sin pasar por la alimentación AMS de P1P.",
    "text.0722": "La cantidad de lavado de las 4 ranuras originales se mantiene según la tabla fuente; para los nuevos colores, se usa el valor máximo de la tabla fuente como valor temporal. Antes de rebanar, se debe recalcular la cantidad de lavado según los nuevos colores.",
    "text.0723": "La tabla de colores oficial se usa para vista previa en pantalla, la apariencia semitransparente es indicativa; no se verificó inventario, precio o diferencia de color real.",
    "text.0724": "La placa 1 contiene varios colores de TPU; estos materiales blandos no pueden cambiar de color automáticamente mediante AMS, el comerciante debe dividir las tareas o organizar el cambio de material por separado. El proyecto actual mantiene la colocación original.",
    "text.0725": "Algunas placas PLA contienen varios colores, necesitan coincidir con el AMS real / plan de cambio de material y verificar la torre de limpieza de material.",
    "text.0726": "Esta versión soporta como máximo ",
    "text.0727": " ranuras de consumible (incluyendo las 4 ranuras originales), por favor reduce los colores antes de exportar.",
    "text.0728": " Aún no se ha seleccionado un consumible real; el color objetivo no se puede exportar directamente como producto.",
    "text.0729": " Se debe mantener ",
    "text.0730": ", no se puede reemplazar el material o la dureza.",
    "error.auth.required": "Por favor inicia sesión primero",
