    "text.0718": "Layout da placa e capa renderizados novamente com a malha atual e materiais selecionados. Modelos/perfis de fotos do autor original em Auxiliaries são apenas referência histórica, não foram modificados. IDs de imagens originais mantidas.",
    "text.0719": "Mantidos os 4 slots originais, cores novas adicionadas com mesmo template; parâmetros como material, dureza, fluxo e temperatura copiados do slot original. Informações de identificação do produto registradas nesta lista.",
    "text.0720": "Exportado como projeto editável, não inclui G-code fatiado. Revise e fatie novamente no Bambu Studio.",
    "text.0721": "TPU 90A mantém a dureza e os parâmetros originais, usando alimentação externa, sem passar pelo AMS de alimentação P1P.",
    "text.0722": "A quantidade de lavagem das 4 ranhuras originais mantém os valores da tabela fonte; novos valores entre cores usam o valor máximo da tabela fonte como valor temporário. Antes de fatiar, é necessário recalcular a lavagem de acordo com as novas cores.",
    "text.0723": "A tabela de cores oficial é usada para pré-visualização na tela, aparência translúcida é apenas ilustrativa; estoque, preço ou diferença de cor real não foram verificados.",
    "text.0724": "A placa 1 contém várias cores de TPU; esses materiais macios não podem trocar de cor automaticamente pelo AMS, o vendedor precisa dividir a tarefa ou organizar a troca de material. O projeto atual mantém a disposição original.",
    "text.0725": "Algumas placas PLA contêm múltiplas cores, precisam corresponder ao AMS/troca de material real e verificar a torre de limpeza de material.",
    "text.0726": "Esta versão suporta no máximo ",
    "text.0727": " slots de material (incluindo os 4 originais), por favor, reduza as cores antes de exportar.",
    "text.0728": " O material real ainda não foi selecionado; a cor alvo não pode ser exportada diretamente como produto.",
    "text.0729": " É necessário manter ",
    "text.0730": ", não é possível substituir material ou dureza.",
