    "error.export.26": "{v0} должен оставаться {v1}, нельзя менять материал или жесткость",
    "error.export.27": "Повторяющийся или несовпадающий идентификатор исходной детали",
    "error.export.28": "Неправильный формат миниатюры",
    "error.validation.29": "Таблица цветов расходников не загружена",
    "error.validation.30": "Сервер не загрузил ресурсы модели, экспорт пока невозможен",
    "error.validation.31": "Сервер не загрузил ресурсы модели, экспорт пока невозможен",
    "text.0718": "Панель и обложка будут перерисованы с текущей сеткой и выбранными расходниками. Model/Profile Pictures оригинального автора в Auxiliaries — историческая справка, не изменялась. ID диаграммы сохранен оригинальный",
    "text.0719": "Оригинальные 4 слота сохранены, новые цвета добавлены по шаблону того же материала; параметры вроде материала, жесткости, расхода, температуры скопированы из оригинального слота. Информация об идентификации продукта записана в этот список",
    "text.0720": "Экспортируемый проект редактируемый, не содержит нарезанный G-code. Проверьте и повторно нарежьте в Bambu Studio",
    "text.0721": "TPU 90A сохраняет исходную твердость и параметры, используется внешняя подача, не через подачу AMS P1P.",
    "text.0722": "Исходный расход для 4-х канального патента сохраняется; новые цвета используют максимальное значение из исходной таблицы как временное. До нарезки нужно пересчитать расход для нового цвета.",
    "text.0723": "Официальная цветовая палитра используется для предварительного просмотра на экране, полупрозрачный вид только для примера; не проверены запасы, цены или реальные цветовые различия.",
    "text.0724": "Плата 1 содержит несколько цветов TPU; эти мягкие материалы нельзя автоматически поменять через AMS, нужно, чтобы продавец разбил задачу или организовал замену материалов отдельно. В текущем проекте сохраняется исходная расстановка.",
    "text.0725": "Некоторые PLA платы содержат несколько цветов, нужно сопоставить с фактической схемой AMS / замены материалов и проверить башню чистки материала.",
    "text.0726": "Эта версия поддерживает максимум ",
    "text.0727": " слотов для расходных материалов (включая исходные 4 слота), пожалуйста, уменьшите количество цветов перед экспортом.",
    "text.0728": " Фактические расходные материалы еще не выбраны; целевой цвет нельзя экспортировать как продукт напрямую.",
    "text.0729": " Нужно сохранить ",
    "text.0730": ", нельзя заменять материал или твердость.",
    "error.auth.required": "Пожалуйста, сначала войдите в систему",
