    "text.0782": "{v16} — та же модель",
    "text.0783": "цвет {v19}",
    "text.0784": "Скопировать ссылку «{v21}»",
    "text.0785": "Скопировать ссылку",
    "text.0786": "Делюсь постером к «{v23}».",
    "text.0787": "Чтение произведения...",
    "text.0788": "Возвращение на площадь цветовой гаммы",
    "text.0789": "В настоящее время не могу прочитать этот текст",
    "text.0790": "Эта работа временно недоступна",
    "text.0791": "Соединение не удалось, пожалуйста, попробуйте позже.",
    "text.0792": "Работа могла быть удалена или ссылка неполная.",
    "text.0793": "Повторная попытка",
    "text.0794": "Просмотр общей работы",
    "text.0795": "Откройте рабочий →",
    "text.0796": "Также доступен с расходниками {v0}",
    "text.0797": "Отсканируйте код, чтобы увидеть этот материал",
    "text.0798": "Моя цветовая модель XGO Duck",
    "text.0799": "Вход не требуется, можно сделать ту же модель после открытия.",
    "text.0800": "Скопировать полноцветный код и создать тот же стиль в Соберём утку.",
    "text.0801": "Тесное совместное использование",
    "text.0802": "Отправьте свою любимую цветовую гамму друзьям.",
    "text.0803": "Отсканируйте QR-код или откройте ссылку, чтобы посмотреть этот материал напрямую.",
    "text.0804": "Скопировать ссылку на работу",
    "text.0805": "Автоматическое копирование не удалось. Пожалуйста, выберите ссылку ниже для копирования.",
    "text.0806": "Вручную скопировать ссылку на работу",
    "text.0807": "Сохранить плакат",
    "text.0808": "Предварительный просмотр открытой ссылки",
    "text.0809": "Дополнительные настройки для постеров",
    "text.0810": "Создание плакатов не удалось. Пожалуйста, откройте снова и попробуйте снова",
    "text.0811": "Постер создан. Пожалуйста, проверьте для скачивания из браузера",
    "text.0812": "Изображение скопировано и может быть вставлено друзьям",
    "text.0813": "Этот браузер не поддерживает копирование изображений. Пожалуйста, используйте «Сохранить плакат»",
    "text.0814": "Ссылка на работу скопирована",
    "text.0815": "Ещё не скопировано",
    "text.0816": "Поделиться «{v0}»",
    "text.0817": "Друзья могут просматривать работы без входа в систему.",
    "text.0818": "Это предложение ещё не опубликовано, и на постере нет QR-кода работы. Вы можете сначала скопировать цветовой код или разместить его на площади и затем поделиться работой.",
    "text.0819": "Сайт пока не установил официальный адрес для совместного использования, поэтому ссылки на произведения пока недоступны.",
    "text.0820": "Ссылка на произведения",
    "text.0821": "Ещё не скопировано, пожалуйста, выберите ссылку вручную",
    "text.0822": "Поиск цветовых схем",
    "text.0823": "Квадратная навигация",
