    "language.auto": "अपने आप चुनें",
    "language.browser": "ब्राउज़र की भाषा अपनाएँ",
    "language.remember": "आपकी पसंद याद रहेगी। कभी भी अपने आप चुनने वाले मोड पर लौटें।",
