    "error.validation.1": "रंग डेटा का फ़ॉर्मेट सही नहीं है",
    "error.validation.2": "रंग में सभी {v0} भाग शामिल होने चाहिए",
    "error.validation.3": "बनावट का फ़ॉर्मेट सही नहीं है",
